(function(t){t.JobLabContent=Object.assign(t.JobLabContent||{},{"KK-951":{scenario:{company:"Huong Dong Beverages",supervisor:{name:"Khúc Đình Viễn",role:{vi:"Trưởng phòng Nghiên cứu & Phát triển sản phẩm",en:"Head of Product R&D"}},ref_code:"NPD-4418",title:{vi:"Đúng nhóm thực phẩm. Đủ giá trị tiệt trùng. An toàn từng lon.",en:"Right food class. Enough lethality. Safe in every can."},brief:{vi:"Bạn rà soát hồ sơ quy trình NPD-4418 cho sữa bắp đóng lon 240 mL (pH 6.5, aw 0.98). Mẻ thử được giữ nhiệt 10 phút; cảm biến buồng nồi hấp ghi 121°C, đầu dò điểm lạnh trong lon ghi 118°C suốt thời gian giữ. Tiêu chuẩn nội bộ yêu cầu F0 ≥ 6 phút. Dùng terminal đọc nhật ký, sửa nhóm axit của sản phẩm và giá trị F0 đạt được, rồi lập báo cáo có căn cứ.",en:"You are reviewing process file NPD-4418 for a 240 mL canned corn milk drink (pH 6.5, aw 0.98). The trial batch was held for 10 minutes; the retort chamber sensor read 121°C while the cold-spot probe inside the can read 118°C throughout the hold. The internal specification requires F0 ≥ 6 minutes. Use the terminal to read the logs, correct the product acid class and the achieved F0, then write an evidence-based report."},reference_title:{vi:"Phiếu đặc tính sản phẩm & báo cáo thâm nhập nhiệt đã duyệt · NPD-4418",en:"Approved product profile & heat penetration report · NPD-4418"},fields:[{id:"ACID_CLASS",label:{vi:"Nhóm axit của sản phẩm",en:"Product acid class"},initial:"ACID",expected:"LOW-ACID",choices:["ACID","ACIDIFIED","LOW-ACID"],reference:"Phiếu đặc tính sản phẩm (pH, aw)",hint:{vi:"pH lớn hơn 4.6 và aw lớn hơn 0.85 là thực phẩm ít axit, phải tiệt trùng thương mại bằng nồi hấp áp lực.",en:"pH above 4.6 and aw above 0.85 means a low-acid food that needs commercial sterilisation in a pressure retort."}},{id:"F0_VALUE",label:{vi:"Giá trị F0 đạt được (phút)",en:"Achieved F0 (minutes)"},initial:"9.77",expected:"4.9",reference:"Báo cáo thâm nhập nhiệt tại điểm lạnh",ref_value:{vi:"Điểm lạnh 118°C trong 10 phút giữ; L(118°C) = 0.490; L(121°C) = 0.977",en:"Cold spot 118°C for the 10-minute hold; L(118°C) = 0.490; L(121°C) = 0.977"},hint:{vi:"F0 tính theo nhiệt độ tại điểm lạnh nhất của sản phẩm, không theo nhiệt độ buồng nồi hấp.",en:"F0 is based on the product cold-spot temperature, not the retort chamber temperature."}}],sop32:{vi:"F0 (phút) = hệ số gây chết L tại nhiệt độ điểm lạnh x thời gian giữ nhiệt; bỏ qua pha nâng và hạ nhiệt (an toàn); bảng L: 115°C 0.245, 118°C 0.490, 121°C 0.977.",en:"F0 (minutes) = lethal rate L at the cold-spot temperature x hold time; ignore come-up and cooling (conservative); L table: 115°C 0.245, 118°C 0.490, 121°C 0.977."},context:{label:"RETORT LOG / NPD-4418",metrics:[{label:{vi:"Nhiệt độ buồng",en:"Chamber temperature"},value:"121°C"},{label:{vi:"Nhiệt độ điểm lạnh",en:"Cold-spot temperature"},value:"118°C"},{label:{vi:"Thời gian giữ nhiệt",en:"Hold time"},value:"10 min"},{label:{vi:"F0 yêu cầu",en:"Required F0"},value:"≥ 6 min"}]},crisis:{vi:"Quản đốc sản xuất nhắn: “Buồng nồi đạt 121°C rồi, cứ ghi F0 9.77 và nhóm ACID cho đỡ phải chạy lại. Mẻ thử này phải gửi khách hàng nếm thử sáng mai.”",en:"The production supervisor messages you: “The chamber reached 121°C, just record F0 9.77 and class ACID so we don't have to rerun. This trial batch must go to the customer for tasting tomorrow morning.”"},options:{safe:{vi:"Cách ly mẻ thử T-07, không gửi khách; báo trưởng phòng R&D và QA; đề xuất kéo dài thời gian giữ nhiệt (tối thiểu 13 phút ở 118°C điểm lạnh) và thẩm định lại bằng thử thâm nhập nhiệt.",en:"Quarantine trial batch T-07 and do not send it; inform the R&D head and QA; propose a longer hold (at least 13 minutes at a 118°C cold spot) and revalidate with a heat penetration test."},shortcut:{vi:"Ghi F0 9.77 theo nhiệt độ buồng và nhóm ACID, gửi mẻ thử cho khách rồi điều chỉnh quy trình sau.",en:"Record F0 9.77 from the chamber temperature and class ACID, ship the trial batch and fix the process later."},wait:{vi:"Không ký hồ sơ và chờ quản đốc tự quyết định có gửi mẫu hay không.",en:"Leave the file unsigned and let the supervisor decide whether to send the samples."}},questions:{vi:["Vì sao sản phẩm thuộc nhóm LOW-ACID và F0 chỉ đạt 4.9 phút? Nhật ký nào trong terminal chứng minh?","Bạn xử lý mẻ thử T-07 và sửa quy trình thế nào để đạt F0 ≥ 6 phút mà vẫn kiểm soát rủi ro Clostridium botulinum?"],en:["Why is the product LOW-ACID and why does F0 reach only 4.9 minutes? Which terminal logs prove it?","How do you handle trial batch T-07 and revise the process to reach F0 ≥ 6 minutes while controlling the Clostridium botulinum risk?"]},hints:{vi:["Chạy cat spec.txt và so pH, aw với ngưỡng phân loại thực phẩm ít axit.","So sánh chamber.log với coldspot.log, rồi nhân hệ số L đúng nhiệt độ với thời gian giữ theo SOP mục 3.2.","Đọc lại SOP mục 4.2: sản phẩm chưa đạt giá trị tiệt trùng phải được cách ly, không xuất xưởng."],en:["Run cat spec.txt and compare pH and aw with the low-acid thresholds.","Compare chamber.log with coldspot.log, then multiply the correct L value by the hold time as in SOP 3.2.","Re-read SOP 4.2: product below the required lethality must be quarantined, never released."]},terminal:{system:"retort-scada",settable:["ACID_CLASS","F0_VALUE"],commands:[{cmd:"status",out:{vi:"Nồi hấp R2 · mẻ thử T-07 · sữa bắp lon 240 mL · chu trình đã kết thúc, chờ phê duyệt xuất mẫu",en:"Retort R2 · trial batch T-07 · corn milk 240 mL can · cycle complete, awaiting release approval"}},{cmd:"cat spec.txt",out:{vi:"Đặc tính sản phẩm: pH 6.5 · aw 0.98 · lon kim loại ghép kín · bảo quản ở nhiệt độ thường",en:"Product profile: pH 6.5 · aw 0.98 · hermetically sealed metal can · ambient storage"}},{cmd:"cat chamber.log",out:{vi:"Buồng nồi hấp: giữ 121.0°C trong 10 phút · áp suất ổn định · không có cảnh báo",en:"Retort chamber: held at 121.0°C for 10 minutes · stable pressure · no alarms"}},{cmd:"cat coldspot.log",out:{vi:"Đầu dò điểm lạnh lon số 3: 118.0°C suốt 10 phút giữ nhiệt · chậm hơn buồng 3°C",en:"Cold-spot probe in can 3: 118.0°C throughout the 10-minute hold · 3°C below the chamber"}},{cmd:"cat lethality.txt",out:{vi:"Bảng hệ số gây chết (Tref 121.1°C, z 10°C): 115°C 0.245 · 118°C 0.490 · 121°C 0.977",en:"Lethal rate table (Tref 121.1°C, z 10°C): 115°C 0.245 · 118°C 0.490 · 121°C 0.977"}}]}},learning:{summary:{vi:"Kỹ sư công nghệ thực phẩm và phát triển sản phẩm biến ý tưởng thành sản phẩm thương mại: xây dựng công thức, chọn nguyên liệu, thiết kế quy trình chế biến và bảo quản, thử cảm quan, xác định hạn sử dụng và chuyển giao sang sản xuất quy mô lớn. Nghề đòi hỏi nền tảng hóa sinh, vi sinh, kỹ thuật nhiệt và luôn đặt an toàn thực phẩm lên trước chi phí và tiến độ.",en:"A food technologist and product developer turns ideas into commercial products: formulating recipes, choosing ingredients, designing processing and preservation steps, running sensory tests, setting shelf life and scaling up to full production. The role requires biochemistry, microbiology and thermal processing knowledge and always puts food safety ahead of cost and deadlines."},responsibilities:{vi:["Nghiên cứu nhu cầu, xây dựng và tối ưu công thức sản phẩm mới theo chi phí mục tiêu.","Thiết kế quy trình chế biến, chế độ thanh trùng hoặc tiệt trùng và thông số kiểm soát.","Tổ chức thử cảm quan, phân tích lý hóa, vi sinh và nghiên cứu hạn sử dụng.","Chuyển giao từ phòng thí nghiệm sang sản xuất thử và sản xuất hàng loạt.","Lập hồ sơ kỹ thuật, thông tin nhãn và hồ sơ tự công bố sản phẩm theo quy định."],en:["Research needs and develop and optimise new product formulas against a target cost.","Design processing steps, pasteurisation or sterilisation regimes and control parameters.","Run sensory, physicochemical, microbiological and shelf-life studies.","Scale up from the laboratory to pilot runs and full production.","Prepare technical files, label information and product self-declaration dossiers."]},competencies:[{name:{vi:"Xây dựng công thức",en:"Formulation"},desc:{vi:"Cân bằng hương vị, cấu trúc, dinh dưỡng, độ ổn định và chi phí nguyên liệu.",en:"Balance taste, texture, nutrition, stability and ingredient cost."}},{name:{vi:"Kỹ thuật xử lý nhiệt",en:"Thermal processing"},desc:{vi:"Tính F0, giá trị thanh trùng và thẩm định chế độ nhiệt bằng thử thâm nhập nhiệt.",en:"Calculate F0 and pasteurisation values and validate regimes with heat penetration tests."}},{name:{vi:"Cảm quan & hạn sử dụng",en:"Sensory & shelf life"},desc:{vi:"Thiết kế phép thử cảm quan và nghiên cứu hạn dùng thực tế hoặc gia tốc.",en:"Design sensory tests and real-time or accelerated shelf-life studies."}},{name:{vi:"Chuyển giao sản xuất",en:"Scale-up"},desc:{vi:"Chuyển công thức từ mẻ nhỏ sang dây chuyền, xử lý chênh lệch thiết bị và nguyên liệu.",en:"Move recipes from bench batches to the line and resolve equipment and ingredient differences."}},{name:{vi:"An toàn ngay từ thiết kế",en:"Safety by design"},desc:{vi:"Phân tích mối nguy từ giai đoạn ý tưởng và từ chối phát hành sản phẩm chưa được thẩm định.",en:"Analyse hazards from the concept stage and refuse to release unvalidated products."}}],knowledge:{vi:["Luật An toàn thực phẩm số 55/2010/QH12 và Nghị định 15/2018/NĐ-CP về tự công bố sản phẩm.","Nghị định 43/2017/NĐ-CP về nhãn hàng hóa, sửa đổi bởi Nghị định 111/2021/NĐ-CP.","Quy phạm thực hành vệ sinh Codex cho thực phẩm đóng hộp ít axit và axit hóa (CXC 23-1979).","Động học tiêu diệt vi sinh vật: giá trị D, z, F0 và mức tiệt trùng 12D đối với Clostridium botulinum.","Hoạt độ nước, pH và công nghệ rào cản (hurdle technology) trong bảo quản thực phẩm."],en:["Food Safety Law No. 55/2010/QH12 and Decree 15/2018/ND-CP on product self-declaration.","Decree 43/2017/ND-CP on goods labelling, amended by Decree 111/2021/ND-CP.","Codex code of hygienic practice for low-acid and acidified low-acid canned foods (CXC 23-1979).","Microbial inactivation kinetics: D, z and F0 values and the 12D botulinum cook.","Water activity, pH and hurdle technology in food preservation."]},tools:["Máy đo pH & hoạt độ nước (aw)","Nồi hấp tiệt trùng thử nghiệm","Bộ ghi nhiệt thâm nhập (thermocouple)","Khúc xạ kế đo độ Brix","Phần mềm tính dinh dưỡng & chi phí công thức"],kpis:{vi:["Tỷ lệ sản phẩm mới ra thị trường đúng tiến độ.","Chi phí nguyên liệu trên đơn vị so với mục tiêu.","Số sự cố chất lượng, an toàn sau khi chuyển giao sản xuất (mục tiêu bằng 0).","Điểm chấp nhận cảm quan của nhóm người tiêu dùng mục tiêu."],en:["Share of new products launched on schedule.","Ingredient cost per unit versus target.","Quality or safety incidents after scale-up (target zero).","Sensory acceptance score from the target consumer panel."]},day:[{time:"08:00",vi:"Họp dự án sản phẩm mới, cập nhật phản hồi của khách hàng thử.",en:"New product project meeting and review of customer trial feedback."},{time:"09:30",vi:"Pha chế mẫu công thức, đo Brix, pH, độ nhớt và ghi biên bản thí nghiệm.",en:"Make formula samples, measure Brix, pH and viscosity and log the trial."},{time:"11:00",vi:"Chạy thử nồi hấp, gắn đầu dò điểm lạnh vào lon mẫu.",en:"Run a trial retort cycle with cold-spot probes in sample cans."},{time:"14:00",vi:"Tổ chức đánh giá cảm quan với hội đồng nội bộ.",en:"Run a sensory evaluation with the internal panel."},{time:"16:00",vi:"Tính F0, chi phí công thức và cập nhật hồ sơ kỹ thuật sản phẩm.",en:"Calculate F0 and formula cost and update the technical file."}],mistakes:{vi:["Tính giá trị tiệt trùng theo nhiệt độ buồng nồi hấp thay vì điểm lạnh của sản phẩm.","Xếp sai nhóm axit, chỉ thanh trùng cho thực phẩm ít axit cần tiệt trùng.","Đổi nguyên liệu, độ nhớt hoặc cỡ bao bì mà không thẩm định lại chế độ nhiệt."],en:["Calculating lethality from the retort chamber instead of the product cold spot.","Misclassifying acidity and only pasteurising a low-acid food that needs sterilisation.","Changing ingredients, viscosity or pack size without revalidating the thermal process."]},career:[{vi:"Kỹ thuật viên phòng thí nghiệm R&D",en:"R&D laboratory technician"},{vi:"Kỹ sư phát triển sản phẩm",en:"Product development engineer"},{vi:"Trưởng nhóm phát triển sản phẩm",en:"Product development team lead"},{vi:"Giám đốc nghiên cứu & phát triển",en:"Research & development director"}],glossary:[{term:"F0",vi:"Thời gian tương đương (phút) ở 121.1°C với z 10°C mà quá trình nhiệt đạt được.",en:"Equivalent minutes at 121.1°C with z 10°C delivered by a thermal process."},{term:"D value",vi:"Thời gian ở một nhiệt độ để giảm 90% (một bậc logarit) quần thể vi sinh vật.",en:"Time at a given temperature to reduce a microbial population by 90% (one log)."},{term:"Low-acid food",vi:"Thực phẩm ít axit: pH lớn hơn 4.6 và aw lớn hơn 0.85, cần tiệt trùng thương mại.",en:"Food with pH above 4.6 and aw above 0.85 that needs commercial sterilisation."},{term:"Water activity (aw)",vi:"Hoạt độ nước: lượng nước tự do vi sinh vật có thể sử dụng, từ 0 đến 1.",en:"Free water available to microorganisms, on a scale from 0 to 1."},{term:"Cold spot",vi:"Điểm lạnh: vị trí trong bao bì nóng lên chậm nhất, dùng để tính giá trị tiệt trùng.",en:"The slowest-heating point in the pack, used to calculate lethality."}],quiz:[{q:{vi:"Thực phẩm đóng hộp nào sau đây là thực phẩm ít axit cần tiệt trùng bằng nồi hấp?",en:"Which canned food below is a low-acid food requiring retort sterilisation?"},options:{vi:["Nước cam pH 3.6","Dưa chuột ngâm giấm pH 4.0","Sữa bắp pH 6.5, aw 0.98","Mứt dâu aw 0.80"],en:["Orange juice pH 3.6","Pickled cucumber pH 4.0","Corn milk pH 6.5, aw 0.98","Strawberry jam aw 0.80"]},answer:2,explain:{vi:"Sữa bắp có pH lớn hơn 4.6 và aw lớn hơn 0.85 nên là thực phẩm ít axit, bào tử Clostridium botulinum có thể phát triển.",en:"Corn milk has pH above 4.6 and aw above 0.85, so it is low-acid and Clostridium botulinum spores can grow."}},{q:{vi:"Điểm lạnh giữ 118°C (L = 0.490) trong 20 phút. F0 đạt được là bao nhiêu?",en:"The cold spot is held at 118°C (L = 0.490) for 20 minutes. What F0 is achieved?"},options:{vi:["9.8 phút","20 phút","19.5 phút","4.9 phút"],en:["9.8 min","20 min","19.5 min","4.9 min"]},answer:0,explain:{vi:"F0 = L x thời gian = 0.490 x 20 = 9.8 phút.",en:"F0 = L x time = 0.490 x 20 = 9.8 minutes."}},{q:{vi:"Mẻ sản phẩm chưa đạt F0 yêu cầu nhưng khách hàng đang chờ mẫu. Bạn làm gì?",en:"A batch has not reached the required F0 but the customer is waiting for samples. What do you do?"},options:{vi:["Gửi mẫu kèm ghi chú","Cách ly mẻ, báo QA và chạy lại theo quy trình đã thẩm định","Sửa F0 trên hồ sơ cho đạt","Chờ quản đốc quyết định"],en:["Send samples with a note","Quarantine the batch, inform QA and rerun a validated process","Edit F0 in the file to pass","Wait for the supervisor to decide"]},answer:1,explain:{vi:"Sản phẩm thiếu giá trị tiệt trùng có nguy cơ ngộ độc botulinum; phải cách ly và chạy lại theo quy trình đã thẩm định.",en:"Under-processed product carries a botulism risk; it must be quarantined and reprocessed under a validated regime."}},{q:{vi:"Mức tiệt trùng 12D đối với Clostridium botulinum nghĩa là gì?",en:"What does a 12D process for Clostridium botulinum mean?"},options:{vi:["Giữ nhiệt 12 phút","Bảo quản 12 ngày","Nhiệt độ cao hơn chuẩn 12°C","Giảm 12 bậc logarit quần thể bào tử"],en:["Hold for 12 minutes","Store for 12 days","Run 12°C above reference","Reduce the spore population by 12 logs"]},answer:3,explain:{vi:"12D là thời gian bằng 12 lần giá trị D, giảm quần thể bào tử 10 mũ 12 lần, tương ứng F0 tối thiểu khoảng 3 phút.",en:"12D equals 12 times the D value, a 10 to the 12th reduction in spores, equivalent to a minimum F0 of about 3 minutes."}}],tools_en:["pH & water activity (aw) meter","Pilot retort sterilizer","Heat penetration data logger (thermocouple)","Brix refractometer","Recipe nutrition & costing software"]}}})})(window.KKR);
